INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-014', TRUE, '图书馆', '2026-10-29', '新闻2026.10.29图书馆举办2026年第3场青禾讲坛读书报告会', '讲座培训', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "本网讯 10月28日晚，青禾讲坛2026年第3场读书报告会在图书馆第一报告厅举行，中国科学技术大学先", "quote": "本网讯 10月28日晚，青禾讲坛2026年第3场读书报告会在图书馆第一报告厅举行，中国科学技术大学先"}]'::jsonb, '讲座培训：新闻2026.10.29图书馆举办2026年第3场青禾讲坛读书报告会', '[{"text": "本网讯 10月28日晚，青禾讲坛2026年第3场读书报告会在图书馆第一报告厅举行，中国科学技术大学先", "quote": "本网讯 10月28日晚，青禾讲坛2026年第3场读书报告会在图书馆第一报告厅举行，中国科学技术大学先"}]'::jsonb, '本网讯 10月28日晚，青禾讲坛2026年第3场读书报告会在图书馆第一报告厅举行，中国科学技术大学先进技术研究院副院长、数学科学学院教授张举勇老师受邀为我校师生作题为《从现实到虚拟，再到现实——人工智能的三维世界》的读书报告，500余名师生参加报告会。 张举勇从生活中常见的有趣现象和前沿科技案例出发，介绍了人工智能在三维重建、数字内容生成、数字孪生和具身智能等方面的基本应用，展示了计算机如何将现实世界转化为可计算、可交互、可创造的数字空间，并进一步赋能机器人与智能系统；帮助同学们认识人工智能的发展趋势，启发大家对未', 'https://lib.ahau.edu.cn/info/2391/55321.htm', '图书馆 · 新闻公告', 'lib', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at